fn get_sound(key: &str) -> JRef<dyn Sound> {
    // Java: Registry.SOUNDS.getOrThrow(Key.key(Key.MINECRAFT_NAMESPACE, key)); a minecraft-namespaced
    // NamespacedKey is that Key.
    crate::org::bukkit::registry::SOUNDS.get_or_throw_1_2(NamespacedKey::minecraft(key))
} // paper-api/src/main/java/org/bukkit/Sound.java:4010
pub fn value_of(name: &str) -> JRef<dyn Sound> {
    let key = NamespacedKey::from_string(&name.to_lowercase());
    let mut sound: Option<JRef<dyn Sound>>;

    if let Some(key) = key {
        // PORT: UnsafeValues.get(RegistryKey, NamespacedKey) is generic, so it is not callable on a
        // `dyn UnsafeValues` until the trait erases its type parameter.
        sound = crate::org::bukkit::bukkit::Bukkit::get_unsafe().get_2(crate::io::papermc::paper::registry::registry_key::SOUND_EVENT.clone(), key);
        if let Some(sound) = sound {
            return sound;
        }
    }

    // Sound keys can have dots in them which where converted to _. Since converting
    // the _ back to a dot would be to complex (since not all _ need to be converted back) we use the field name.
    sound = field(name).map(|f| LazyLock::force(f).clone());

    if sound.is_none() {
        panic!("IllegalArgumentException: No sound found with the name {}", name);
    }
    sound.unwrap()
} // paper-api/src/main/java/org/bukkit/Sound.java:4020
pub fn values() -> Vec<JRef<dyn Sound>> {
    crate::org::bukkit::registry::SOUNDS.stream().collect()
} // paper-api/src/main/java/org/bukkit/Sound.java:4059
